package com.ahdre.pip;
import android.graphics.*;import android.view.*;import org.json.*;
class VisitTogether {
 final LifeFeatures life;final PetService s;String id,game="none",shelf="";int oldX,oldY,guestRow=3;boolean ownBall;
 VisitTogether(LifeFeatures l){life=l;s=l.s;}
 boolean tick(long now){JSONObject v=life.social.activeVisit();if(v==null||v.optBoolean("outgoing")||v.optInt("features")<2){if(id!=null){id=null;game="none";s.lp.x=oldX;s.lp.y=oldY;s.clamp();s.update();s.extra.ball.setVisibility(View.INVISIBLE);ownBall=false;LifeFeatures.note(s.prefs,"Проводили друга домой. До новой встречи!");s.savePosition();}return false;}
  if(!v.optString("id").equals(id)){oldX=s.lp.x;oldY=s.lp.y;life.stopActivity();life.syncFocus();s.touch();id=v.optString("id");s.extra.ballVisible=false;SocialClient.Pet p=life.social.visitor();LifeFeatures.note(s.prefs,(v.optInt("meetings")>1?"Снова пришёл ":"В гости пришёл ")+p.name+". Встреча №"+v.optInt("meetings")+".");String gift=v.optString("gift","none");if(VisitLife.gift(gift)&&!gift.equals("none"))LifeFeatures.note(s.prefs,"Остался подарок от "+p.name+": "+VisitLife.giftName(gift)+".");}
  double elapsed=System.currentTimeMillis()/1000.0-v.optDouble("gameAt");VisitLife.Frame f=VisitLife.Frame.at(v.optString("game"),elapsed);game=elapsed>=30?"rest":v.optString("game","rest");
  double lane=Math.min(s.dp(320),s.width),left=Math.max(0,Math.min(s.width-lane,s.extra.hp.x-lane*.7));int floor=Math.max(s.dp(24)+Math.max(s.lp.height,life.gp.height),Math.min(s.height-s.dp(28),s.extra.hp.y+s.extra.hp.height));
  s.extra.home.setVisibility(s.extra.homeVisible?View.VISIBLE:View.INVISIBLE);s.lp.x=(int)(left+lane*f.host-s.lp.width/2);s.lp.y=floor-s.lp.height;s.clamp();s.update();life.pose(f.hostRow,f.hostFrame);
  life.gp.x=(int)Math.max(0,Math.min(s.width-life.gp.width,left+lane*f.guest-life.gp.width/2));life.gp.y=floor-life.gp.height;s.wm.updateViewLayout(life.guest,life.gp);guestRow=f.guestRow;life.guestFrame=f.guestFrame;life.guest.setVisibility(View.VISIBLE);life.guest.invalidate();
  if(f.showBall){s.extra.bp.x=(int)(left+lane*f.ball-s.extra.bp.width/2);s.extra.bp.y=(int)(floor-s.extra.bp.height-s.dp((float)f.ballHeight));s.wm.updateViewLayout(s.extra.ball,s.extra.bp);s.extra.ball.setVisibility(View.VISIBLE);s.extra.ball.invalidate();ownBall=true;}else if(ownBall){s.extra.ball.setVisibility(View.INVISIBLE);ownBall=false;}return true;
 }
 void drawShelf(Canvas c,Paint p){try{JSONObject counts=new JSONObject(s.prefs.getString("giftCounts","{}"));String[] kinds={"leaf","toy","card"};for(int i=0;i<3;i++){int n=counts.optInt(kinds[i]);if(n<=0)continue;float x=18+i*45;drawGift(c,p,kinds[i],x,4);p.setColor(Color.rgb(0,100,100));p.setTextSize(12);c.drawText(String.valueOf(n),x+22,28,p);}}catch(JSONException e){}}
 static void drawGift(Canvas c,Paint p,String kind,float x,float y){p.setStyle(Paint.Style.FILL);if(kind.equals("leaf")){p.setColor(Color.rgb(46,139,87));c.drawOval(x,y,x+14,y+24,p);p.setColor(Color.rgb(255,215,0));p.setStrokeWidth(1);c.drawLine(x+2,y+23,x+13,y+3,p);}else if(kind.equals("toy")){p.setColor(Color.rgb(255,165,0));c.drawCircle(x+11,y+14,11,p);p.setColor(Color.rgb(0,128,128));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);c.drawArc(x+2,y+7,x+19,y+19,20,220,false,p);p.setStyle(Paint.Style.FILL);}else{p.setColor(Color.rgb(250,250,210));c.drawRect(x,y+5,x+25,y+23,p);p.setColor(Color.rgb(205,92,92));c.drawCircle(x+12,y+13,4,p);}}
}
